//! Stage S1: Deterministic regional tectonic uplift, caprock stratigraphy, rift/caldera relief,
//! and 6-class lithology generation (`§2.2.1`, using `libm` exclusively for transcendental math).

use crate::config::{ConfigError, WorldV2Config};
use crate::rng::stage_rng;
use crate::LITHOLOGY_CLASS_COUNT;
use rand::Rng;
use rayon::prelude::*;
use sha2::{Digest, Sha256};
use std::f64::consts::TAU;

/// Six canonical stratigraphic/rock lithology classes generated by Stage S1 (`§2.2.1` item 5).
#[repr(u8)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum LithologyClass {
    GraniteCrystalline = 0,
    SandstoneCaprock = 1,
    SolubleLimestone = 2,
    BasaltVolcanic = 3,
    SoftShale = 4,
    UnconsolidatedAlluvium = 5,
}

impl LithologyClass {
    /// Dimensionless relative erodibility factor (`K_mult`). Ratio `max/min = 1.20 / 0.15 = 8.0`.
    #[must_use]
    pub const fn erodibility(self) -> f32 {
        match self {
            Self::GraniteCrystalline => 0.15,
            Self::SandstoneCaprock => 0.22,
            Self::SolubleLimestone => 0.55,
            Self::BasaltVolcanic => 0.30,
            Self::SoftShale => 1.00,
            Self::UnconsolidatedAlluvium => 1.20,
        }
    }
}

/// Output buffers produced deterministically by [`generate_uplift`].
#[derive(Debug, Clone, PartialEq)]
pub struct TectonicField {
    pub width: u32,
    pub height: u32,
    /// Pre-erosion initial elevation in physical metres `[-1,500, +5,700]`.
    pub bedrock_h: Vec<f32>,
    /// Regional tectonic uplift rate proxy field (`>= 0`).
    pub uplift_u: Vec<f32>,
    /// Per-cell lithology ID in `0..6` (`LithologyClass as u8`).
    pub lithology_id: Vec<u8>,
    /// Per-cell erodibility multiplier matching `lithology_id`.
    pub stratum_k: Vec<f32>,
}

impl TectonicField {
    /// Fraction of grid cells strictly below sea level (`bedrock_h < 0.0`).
    #[must_use]
    pub fn ocean_fraction(&self) -> f32 {
        let ocean_count = self.bedrock_h.iter().filter(|&&h| h < 0.0).count();
        ocean_count as f32 / self.bedrock_h.len() as f32
    }

    /// SHA-256 over dimensions and exact little-endian IEEE-754 bytes of all S1 buffers.
    #[must_use]
    pub fn sha256_bytes(&self) -> [u8; 32] {
        let mut hasher = Sha256::new();
        hasher.update(self.width.to_le_bytes());
        hasher.update(self.height.to_le_bytes());
        for &h in &self.bedrock_h {
            hasher.update(h.to_bits().to_le_bytes());
        }
        for &u in &self.uplift_u {
            hasher.update(u.to_bits().to_le_bytes());
        }
        hasher.update(&self.lithology_id);
        for &k in &self.stratum_k {
            hasher.update(k.to_bits().to_le_bytes());
        }
        let digest = hasher.finalize();
        let mut out = [0u8; 32];
        out.copy_from_slice(&digest);
        out
    }
}

#[derive(Debug, Clone, Copy)]
struct TectonicParams {
    seed_u64: u64,
    coast_shift_u: f64,
    ridge_angle_rad: f64,
    ridge_bend: f64,
    volcano_u: f64,
    volcano_v: f64,
    plateau_u: f64,
    plateau_v: f64,
    rift_angle_rad: f64,
    rift_offset_u: f64,
    phase_x: f64,
    phase_z: f64,
}

impl TectonicParams {
    fn from_config_with_grid_size(cfg: &WorldV2Config, params_grid_size: u32) -> Self {
        let mut rng = stage_rng(
            cfg.seed,
            params_grid_size,
            params_grid_size,
            &cfg.schema_tag,
            "S1-TECT",
        );
        Self {
            seed_u64: cfg.seed ^ 0x9E37_79B9_7F4A_7C15,
            coast_shift_u: rng.gen_range(-0.03..0.03),
            ridge_angle_rad: rng.gen_range(-0.14..0.14),
            ridge_bend: rng.gen_range(0.04..0.08),
            volcano_u: rng.gen_range(0.68..0.76),
            volcano_v: rng.gen_range(0.18..0.28),
            plateau_u: rng.gen_range(0.71..0.77),
            plateau_v: rng.gen_range(0.54..0.68),
            rift_angle_rad: rng.gen_range(0.35..0.60),
            rift_offset_u: rng.gen_range(0.56..0.64),
            phase_x: rng.gen_range(0.0..TAU),
            phase_z: rng.gen_range(0.0..TAU),
        }
    }
}

/// Stateless 64-bit SplitMix hash mapped deterministically into `[0.0, 1.0)`.
#[inline]
fn hash_lattice(seed: u64, ix: i64, iz: i64) -> f64 {
    let mut z = seed
        .wrapping_add((ix as u64).wrapping_mul(0xBF58_476D_1CE4_E5B9))
        .wrapping_add((iz as u64).wrapping_mul(0x94D0_49BB_1331_11EB));
    z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
    z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
    z ^= z >> 31;
    (z >> 11) as f64 * (1.0 / ((1u64 << 53) as f64))
}

/// Smooth quintic value noise in `[-1.0, 1.0]` using `libm::floor` only.
#[inline]
fn value_noise(seed: u64, x: f64, z: f64) -> f64 {
    let fx = libm::floor(x);
    let fz = libm::floor(z);
    let ix = fx as i64;
    let iz = fz as i64;
    let tx = x - fx;
    let tz = z - fz;
    let sx = tx * tx * tx * (tx * (tx * 6.0 - 15.0) + 10.0);
    let sz = tz * tz * tz * (tz * (tz * 6.0 - 15.0) + 10.0);

    let v00 = hash_lattice(seed, ix, iz);
    let v10 = hash_lattice(seed, ix + 1, iz);
    let v01 = hash_lattice(seed, ix, iz + 1);
    let v11 = hash_lattice(seed, ix + 1, iz + 1);
    let vx0 = v00 + sx * (v10 - v00);
    let vx1 = v01 + sx * (v11 - v01);
    (vx0 + sz * (vx1 - vx0)) * 2.0 - 1.0
}

#[inline]
fn fbm_4(seed: u64, x: f64, z: f64) -> f64 {
    let mut sum = 0.0;
    let mut amp = 0.5;
    let mut freq = 1.0;
    for octave in 0..4u64 {
        let s = seed.wrapping_add(octave.wrapping_mul(0x517C_C1B7_2722_0A95));
        sum += amp * value_noise(s, x * freq, z * freq);
        freq *= 2.03;
        amp *= 0.5;
    }
    sum
}

#[inline]
fn fbm_coast_fractal(seed: u64, x: f64, z: f64) -> f64 {
    let mut sum = 0.0;
    let mut amp = 0.44;
    let mut freq = 1.0;
    for octave in 0..7u64 {
        let s = seed.wrapping_add(octave.wrapping_mul(0x9E37_79B9_7F4A_7C15));
        sum += amp * value_noise(s, x * freq, z * freq);
        freq *= 2.05;
        amp *= 0.66;
    }
    sum
}

#[inline]
fn fbm_coast_fractal_2d(seed: u64, x: f64, z: f64) -> f64 {
    let mut sum = 0.0;
    let mut amp = 0.45;
    let mut freq = 1.0;
    for octave in 0..8u64 {
        let s = seed.wrapping_add(octave.wrapping_mul(0x9E37_79B9_7F4A_7C15));
        sum += amp * value_noise(s, x * freq, z * freq);
        freq *= 2.04;
        amp *= 0.72;
    }
    sum
}

#[inline]
fn sech2(t: f64) -> f64 {
    let clamped = t.clamp(-12.0, 12.0);
    let c = libm::coshf(clamped as f32) as f64;
    1.0 / (c * c)
}

const STRAT_Z_BASE_M: f64 = 650.0;
const STRAT_DIP_DEG: f64 = 4.0;
const STRAT_FOLD_AMP_M: f64 = 45.0;
/// Minimum stratigraphic bed thickness (`Upper Caprock`, `T_min = 100 m`), bounding `S2` step incision (`<= 25 m`).
pub const STRAT_MIN_BED_THICKNESS_M: f64 = 100.0;
const RIFT_SEGMENT_LEN_M: f64 = 15_000.0;

#[derive(Debug, Clone, Copy)]
struct CellStratGeom {
    fbm_broad: f64,
    in_volcano: bool,
    in_plateau: bool,
    near_rift: bool,
    in_lake_sill: bool,
    ridge_core_dist: f64,
    coast_dist: f64,
    coast_cliff: f64,
    ridge_u: f64,
    u_rot: f64,
    v_rot: f64,
}

#[derive(Debug, Clone, Copy)]
struct CellEval {
    raw_h_m: f64,
    uplift: f64,
    strat: CellStratGeom,
}

#[inline]
fn eval_cell_strat_and_envelope(
    u: f64,
    v: f64,
    p: &TectonicParams,
    cfg: &WorldV2Config,
) -> (CellStratGeom, f64, f64, f64, f64, f64, f64) {
    let fbm_broad = fbm_4(p.seed_u64, u * 4.5, v * 4.5);

    // Rotated regional strike coordinates centered on massif spine.
    let sin_r = libm::sin(p.ridge_angle_rad);
    let cos_r = libm::cos(p.ridge_angle_rad);
    let cu = u - 0.5;
    let cv = v - 0.5;
    let u_rot = cu * cos_r + cv * sin_r + 0.5;
    let v_rot = -cu * sin_r + cv * cos_r + 0.5;

    // 1. Multi-octave fractal windward coastline (`u` oceanward west -> ~45% ocean) + rocky headlands.
    let smooth_coast = 0.45
        + p.coast_shift_u
        + 0.024 * libm::sin(v_rot * TAU * 0.8 + p.phase_z)
        + 0.022 * fbm_broad;
    let smooth_d_coast = u_rot - smooth_coast;
    let coast_scale = (f64::from(cfg.coast_frac_amp) / 0.055).clamp(0.0, 1.5);
    let dw_u = 0.036
        * coast_scale
        * fbm_coast_fractal(p.seed_u64 ^ 0xC0A5_1111_2222_3333, u_rot * 5.0, v_rot * 5.0);
    let dw_v = 0.036
        * coast_scale
        * fbm_coast_fractal(p.seed_u64 ^ 0xC0A5_4444_5555_6666, u_rot * 5.0, v_rot * 5.0);
    let u_c = u_rot + dw_u;
    let v_c = v_rot + dw_v;
    let coast_warp = (f64::from(cfg.coast_frac_amp)
        * 1.8
        * fbm_coast_fractal(p.seed_u64 ^ 0xC0A5_7F12_3456_789A, u_c * 5.0, v_c * 5.0))
    .clamp(-0.060, 0.060);
    let coast_line = (smooth_coast + coast_warp).clamp(0.35, 0.56);
    let d_coast = u_c - coast_line;
    let in_lake_sill = false;

    let c_share = f64::from(cfg.coast_cliff_share).clamp(0.0, 0.70);
    let coast_cliff = if c_share <= 0.01 {
        0.0
    } else {
        let cliff_n = value_noise(p.seed_u64 ^ 0xC11F_F001, u_rot * 3.8, v_rot * 10.5);
        let thr = 0.58 * (1.0 - 2.0 * c_share);
        ((cliff_n - thr) / 0.14).clamp(0.0, 1.0)
    };

    // 2. Active coastal mountain spine (`sech^2` anchored on smooth coast axis, peaking > 5,200 m).
    let ridge_center_u = smooth_coast + 0.22 + p.ridge_bend * libm::cos(v_rot * 3.1 + p.phase_x);
    let dv_ridge = (v_rot - 0.52) / 0.34;
    let along_crest_envelope = libm::exp(-0.55 * dv_ridge * dv_ridge);
    let d_ridge = u_rot - ridge_center_u - 0.025 * fbm_broad;

    let spur_fbm = fbm_4(p.seed_u64 ^ 0x5902_1122_3344_5566, u_rot * 4.8, v_rot * 5.2);
    let spur_wave =
        0.55 * spur_fbm + 0.45 * libm::sin(v_rot * TAU * 3.5 + p.phase_z + 2.2 * fbm_broad);
    let flank_w = (1.0 - sech2(d_ridge / 0.085)).clamp(0.0, 1.0);
    let d_ridge_warped = d_ridge + 0.028 * spur_wave * flank_w;
    let width_asym = if d_ridge_warped < 0.0 { 0.098 } else { 0.115 };
    let flank_spur = flank_w * 0.28 * spur_wave;
    let massif_uplift = sech2(d_ridge_warped / width_asym)
        * (0.74 + 0.26 * along_crest_envelope)
        * (1.0 + 0.20 * fbm_broad.max(-0.15) + flank_spur).max(0.45);
    let crest_spine = sech2(d_ridge / 0.055) * along_crest_envelope;
    let t_pied = ((smooth_d_coast - 0.092) / 0.032).clamp(0.0, 1.0);
    let piedmont_gate = t_pied * t_pied * (3.0 - 2.0 * t_pied);

    let massif_h = piedmont_gate
        * (5_350.0 * massif_uplift
            + 450.0 * along_crest_envelope * sech2((v_rot - 0.5) / 0.4)
            + 260.0 * crest_spine);

    // 3. Normal-fault structural rift trough segmented at L_seg = 15.0 km (`Jackson & White 1989`, p. 16),
    //    forming en-echelon grabens separated by a relay-ramp horst sill.
    let rift_u = (u - p.rift_offset_u) * libm::cos(p.rift_angle_rad)
        + (v - 0.48) * libm::sin(p.rift_angle_rad);
    let rift_v = -(u - p.rift_offset_u) * libm::sin(p.rift_angle_rad)
        + (v - 0.48) * libm::cos(p.rift_angle_rad);
    let l_seg_norm = RIFT_SEGMENT_LEN_M / f64::from(cfg.extent_m).max(1.0);
    let b_amp = f64::from(cfg.basin_amp).clamp(0.5, 3.0);
    let seg_w = 0.032 * (0.95 + 0.45 * b_amp);
    let inv_half_w = 1.0 / (0.48 * l_seg_norm);
    let dv_seg1 = (rift_v + 0.5 * l_seg_norm) * inv_half_w;
    let dv_seg2 = (rift_v - 0.5 * l_seg_norm) * inv_half_w;
    let seg1 = sech2((rift_u + 0.012) / seg_w) * libm::exp(-(dv_seg1 * dv_seg1));
    let seg2 = sech2((rift_u - 0.012) / seg_w) * libm::exp(-(dv_seg2 * dv_seg2));
    let near_rift = (seg1 > 0.26 || seg2 > 0.26) && libm::fabs(rift_u) < 0.075;

    // 4. Horizontal resistant sandstone caprock plateau (~15-20 km leeward tableland).
    let du_plat = (u - p.plateau_u) / 0.268;
    let dv_plat = (v - p.plateau_v) / 0.278;
    let r_plat = libm::hypot(du_plat, dv_plat);
    let plateau_mask = 1.0 / (1.0 + libm::exp((r_plat - 1.0) * 16.0));
    let land_gate = 1.0 / (1.0 + libm::exp(-(smooth_d_coast - 0.06) * 35.0));
    let core_gate = 1.0 / (1.0 + libm::exp((massif_h - 2_400.0) / 300.0));
    let plateau_blend = plateau_mask * land_gate * core_gate;

    // 5. Volcanic stratocone footprint (`BasaltVolcanic`).
    let r_volc = libm::hypot(u - p.volcano_u, v - p.volcano_v);
    let in_volcano = r_volc < 0.095;

    let strat = CellStratGeom {
        fbm_broad,
        in_volcano,
        in_plateau: plateau_blend > 0.35 && !in_volcano,
        near_rift,
        in_lake_sill,
        ridge_core_dist: libm::fabs(d_ridge),
        coast_dist: d_coast,
        coast_cliff,
        ridge_u: ridge_center_u,
        u_rot,
        v_rot,
    };
    (
        strat,
        massif_h,
        massif_uplift,
        plateau_blend,
        rift_u,
        rift_v,
        r_volc,
    )
}

fn eval_cell_raw(u: f64, v: f64, p: &TectonicParams, cfg: &WorldV2Config) -> CellEval {
    let (strat, massif_h, massif_uplift, plateau_blend, rift_u, rift_v, r_volc) =
        eval_cell_strat_and_envelope(u, v, p, cfg);
    let d_coast = strat.coast_dist;
    let fbm_detail = fbm_4(p.seed_u64 ^ 0xA5A5_5A5A_1234_ABCD, u * 14.0, v * 14.0);
    let b_amp = f64::from(cfg.basin_amp).clamp(0.5, 3.0);

    // Asymmetric continental margin: shallow coastal shelf (`0..-22 m` for DeltaRCM delta progradation)
    // dropping to abyssal depths offshore, modulated by a 2D band-limited fractal ria field.
    let t_ria = d_coast / 0.055;
    let ria_amp = 260.0 + 620.0 * strat.coast_cliff;
    let coast_ria_2d = f64::from(cfg.coast_frac_amp)
        * ria_amp
        * fbm_coast_fractal_2d(
            p.seed_u64 ^ 0xC0A5_72D0_9876_5432,
            strat.u_rot * 10.5,
            strat.v_rot * 10.5,
        )
        * libm::exp(-(t_ria * t_ria));
    let shelf_and_margin = if d_coast < 0.0 {
        let shelf_drop = 420.0 * d_coast.max(-0.035);
        let slope_drop = -1_420.0 * libm::tanh((-d_coast - 0.030).max(0.0) / 0.14);
        shelf_drop + slope_drop + coast_ria_2d
    } else {
        let plain_ramp = 90.0 * d_coast.min(0.045);
        let inland_ramp = 250.0 * libm::tanh((d_coast - 0.042).max(0.0) / 0.16);
        plain_ramp + inland_ramp + coast_ria_2d
    };

    // Segmented normal-fault grabens + relay-ramp horst sill (`L_seg = 15.0 km`), plus 3 broad
    // low-slope humid windward piedmont / back-barrier sag basins below `2,000 m` (`endo_humid == 0`,
    // zero glacial moraine disturbance).
    let l_seg_norm = RIFT_SEGMENT_LEN_M / f64::from(cfg.extent_m).max(1.0);
    let seg_w = 0.032;
    let inv_half_w = 1.0 / (0.40 * l_seg_norm);
    let dv_seg1 = (rift_v + 0.5 * l_seg_norm) * inv_half_w;
    let dv_seg2 = (rift_v - 0.5 * l_seg_norm) * inv_half_w;
    let seg1 = sech2((rift_u + 0.012) / seg_w) * libm::exp(-(dv_seg1 * dv_seg1));
    let seg2 = sech2((rift_u - 0.012) / seg_w) * libm::exp(-(dv_seg2 * dv_seg2));
    let t_relay = rift_v / 0.055;
    let t_tip_pos = (rift_v - l_seg_norm) / 0.055;
    let t_tip_neg = (rift_v + l_seg_norm) / 0.055;
    let relay_sill = (165.0 * libm::sqrt(b_amp))
        * sech2(rift_u / 0.058)
        * (libm::exp(-(t_relay * t_relay))
            + libm::exp(-(t_tip_pos * t_tip_pos))
            + libm::exp(-(t_tip_neg * t_tip_neg)));
    let humid_basin_gate = 1.0 / (1.0 + libm::exp((strat.u_rot - (strat.ridge_u + 0.025)) / 0.018));

    let caprock_target_m = 0.52 * f64::from(cfg.caprock_min_m + cfg.caprock_max_m) + 120.0;

    // 5. Volcanic stratocone & wider collapsed caldera crater rim (`BasaltVolcanic`).
    let t_cone = r_volc / 0.072;
    let t_cald = r_volc / 0.030;
    let cone = f64::from(cfg.volcano_relief_m) * libm::exp(-(t_cone * t_cone));
    let caldera = -(520.0 * libm::sqrt(b_amp)) * libm::exp(-(t_cald * t_cald));
    let volcano_h = cone + caldera;

    // 6. Compose base surface + monotonically dipped caprock plateau + volcanic cone.
    let base_surface = shelf_and_margin + massif_h;
    let plateau_surface = caprock_target_m + 34.0 * fbm_detail + 220.0 * (p.plateau_u - u);
    let detail_gate = ((d_coast - 0.038) / 0.025).clamp(0.0, 1.0);
    let pre_basin_h = (1.0 - plateau_blend) * base_surface
        + plateau_blend * plateau_surface
        + volcano_h
        + 95.0
            * fbm_detail
            * detail_gate
            * (1.0 - 0.88 * plateau_blend)
            * libm::exp(-0.3 * d_coast * d_coast);

    // Gate rift drop safely below 2,000 m and above sea level so no depression floods into ocean or disturbs glaciers.
    let low_elev_gate = 1.0 / (1.0 + libm::exp((pre_basin_h - 2_000.0) / 250.0));
    let land_headroom = ((pre_basin_h - 460.0) / 220.0).clamp(0.0, 1.0);
    let rift_mod = if d_coast > 0.075 {
        land_headroom
            * humid_basin_gate
            * low_elev_gate
            * (-(380.0 * libm::sqrt(b_amp)) * (seg1 + seg2) + relay_sill)
    } else {
        0.0
    };

    let mut raw_h_m = pre_basin_h + rift_mod;
    if d_coast > 0.065 {
        let rift_floor = pre_basin_h.min(240.0);
        if raw_h_m < rift_floor {
            raw_h_m = rift_floor;
        }
    }

    let uplift = (f64::from(cfg.massif_uplift_amplitude) * massif_uplift
        + 350.0 * plateau_blend
        + if d_coast > 0.0 { 120.0 } else { 0.0 })
    .max(0.0);

    CellEval {
        raw_h_m,
        uplift,
        strat,
    }
}

/// Amendment A1: Flanking SNSM / Cesar-Ranchería Mesozoic-Paleogene stratigraphic column
/// with advected basal structural datum `z_c(x, y, t) = z_c0(x, y) + U(x, y) * t_elapsed`.
#[inline]
fn assign_lithology_advected(
    h_m: f32,
    geom: &CellStratGeom,
    uplift_m_yr: f64,
    t_elapsed_yr: f64,
    extent_m: f64,
) -> LithologyClass {
    if geom.in_volcano && h_m > 300.0 {
        return LithologyClass::BasaltVolcanic;
    }
    if geom.coast_cliff > 0.36 && (-95.0..=165.0).contains(&f64::from(h_m)) {
        return LithologyClass::GraniteCrystalline;
    }
    if geom.in_lake_sill && h_m > 2.0 && h_m < 450.0 {
        return LithologyClass::GraniteCrystalline;
    }
    if h_m < 140.0 || geom.coast_dist < 0.02 || (geom.near_rift && h_m < 420.0) {
        return LithologyClass::UnconsolidatedAlluvium;
    }
    if h_m > 2_300.0 || geom.ridge_core_dist < 0.06 {
        return LithologyClass::GraniteCrystalline;
    }

    let d_massif_m = geom.ridge_core_dist * extent_m;
    let m_dip = libm::tan(STRAT_DIP_DEG * (std::f64::consts::PI / 180.0));
    let z_c0 = STRAT_Z_BASE_M - m_dip * d_massif_m + STRAT_FOLD_AMP_M * geom.fbm_broad;
    let z_c = z_c0 + uplift_m_yr * t_elapsed_yr;
    let z_rel = f64::from(h_m) - z_c;

    if z_rel < 0.0 {
        LithologyClass::SoftShale
    } else if z_rel < 150.0 {
        LithologyClass::SandstoneCaprock
    } else if z_rel < 500.0 {
        LithologyClass::SolubleLimestone
    } else if z_rel < 650.0 {
        LithologyClass::SoftShale
    } else if z_rel < 750.0 || geom.in_plateau {
        LithologyClass::SandstoneCaprock
    } else {
        LithologyClass::SoftShale
    }
}

/// Calibrates a uniform scalar height shift so `(raw_h + shift) < 0` matches `target_ocean_fraction`.
fn calibrate_sea_level_shift(raw_h: &[f64], target_ocean_fraction: f32) -> f64 {
    let mut low = -2_000.0_f64;
    let mut high = 2_000.0_f64;
    let target = f64::from(target_ocean_fraction);
    let total = raw_h.len() as f64;
    for _ in 0..48 {
        let mid = 0.5 * (low + high);
        let below = raw_h.par_iter().filter(|&&h| h + mid < 0.0).count() as f64;
        let frac = below / total;
        if frac > target {
            low = mid;
        } else {
            high = mid;
        }
    }
    0.5 * (low + high)
}

/// Smoothly and monotonically maps shifted elevation into `(elev_min_m, elev_max_m)` so no
/// flat summit or abyssal plateau is created by hard-clipping extremes.
fn soft_bound_elevation(h_m: f64, elev_min_m: f32, elev_max_m: f32) -> f32 {
    let min_b = f64::from(elev_min_m);
    let max_b = f64::from(elev_max_m);
    let lo_knee = 0.60 * min_b;
    let hi_knee = 0.72 * max_b;

    let mapped = if h_m > hi_knee {
        let span = 0.935 * (max_b - hi_knee);
        hi_knee + span * libm::tanh((h_m - hi_knee) / span)
    } else if h_m < lo_knee {
        let span = 0.995 * (lo_knee - min_b);
        lo_knee - span * libm::tanh((lo_knee - h_m) / span)
    } else {
        h_m
    };

    mapped as f32
}

/// Generates deterministic Stage S1 initial bedrock, uplift, lithology, and erodibility fields.
///
/// Uses a two-pass memory-lean evaluation (`208 MiB` peak at `4096^2`, dropping `raw_h` before
/// allocating outputs) and purely coordinate-indexed `rayon` row parallelism so `1`-thread and
/// `N`-thread `rayon` pools on the same machine yield bit-identical IEEE-754 outputs.
pub fn generate_uplift(cfg: &WorldV2Config) -> Result<TectonicField, ConfigError> {
    generate_uplift_for_target(cfg, cfg.grid_size)
}

/// Generates Stage S1 fields at `cfg.grid_size` while deriving regional structural parameters
/// from `params_grid_size` so coarse-to-fine multigrid levels share identical landform placement.
pub fn generate_uplift_for_target(
    cfg: &WorldV2Config,
    params_grid_size: u32,
) -> Result<TectonicField, ConfigError> {
    cfg.validate()?;
    let w = cfg.grid_size as usize;
    let h = cfg.grid_size as usize;
    let n = w * h;
    let params = TectonicParams::from_config_with_grid_size(cfg, params_grid_size);

    let denom_x = (w - 1) as f64;
    let denom_z = (h - 1) as f64;

    // Pass 1: evaluate only `raw_h_m` (`128 MiB` @ 4096^2) to calibrate sea-level shift, then drop.
    let mut raw_h = vec![0.0_f64; n];
    raw_h
        .par_chunks_mut(w)
        .enumerate()
        .for_each(|(row, row_slice)| {
            let v = row as f64 / denom_z;
            for (col, slot) in row_slice.iter_mut().enumerate() {
                let u = col as f64 / denom_x;
                *slot = eval_cell_raw(u, v, &params, cfg).raw_h_m;
            }
        });

    let shift = calibrate_sea_level_shift(&raw_h, cfg.target_ocean_fraction);
    drop(raw_h);

    // Pass 2: evaluate directly into the 4 output slices (`208 MiB` @ 4096^2).
    let mut bedrock_h = vec![0.0_f32; n];
    let mut uplift_u = vec![0.0_f32; n];
    let mut lithology_id = vec![0_u8; n];
    let mut stratum_k = vec![0.0_f32; n];

    let extent_m = f64::from(cfg.extent_m);
    bedrock_h
        .par_chunks_mut(w)
        .zip(uplift_u.par_chunks_mut(w))
        .zip(lithology_id.par_chunks_mut(w))
        .zip(stratum_k.par_chunks_mut(w))
        .enumerate()
        .for_each(|(row, (((bh, uu), lid), sk))| {
            let v = row as f64 / denom_z;
            for col in 0..w {
                let u = col as f64 / denom_x;
                let ev = eval_cell_raw(u, v, &params, cfg);
                let base_elev =
                    soft_bound_elevation(ev.raw_h_m + shift, cfg.elev_min_m, cfg.elev_max_m);
                let elev =
                    if ev.strat.coast_cliff > 0.01 && libm::fabs(f64::from(base_elev)) < 260.0 {
                        let e = f64::from(base_elev);
                        let cc = ev.strat.coast_cliff;
                        let boost = if e > 0.0 {
                            138.0 * cc * libm::tanh(e / 14.0) * libm::exp(-e / 140.0)
                        } else {
                            -105.0 * cc * libm::tanh((-e) / 14.0) * libm::exp(-(-e) / 140.0)
                        };
                        soft_bound_elevation(e + boost, cfg.elev_min_m, cfg.elev_max_m)
                    } else {
                        base_elev
                    };
                let class = assign_lithology_advected(elev, &ev.strat, 0.0, 0.0, extent_m);
                bh[col] = elev;
                uu[col] = ev.uplift as f32;
                lid[col] = class as u8;
                debug_assert!((lid[col] as usize) < LITHOLOGY_CLASS_COUNT);
                sk[col] = class.erodibility();
            }
        });

    Ok(TectonicField {
        width: cfg.grid_size,
        height: cfg.grid_size,
        bedrock_h,
        uplift_u,
        lithology_id,
        stratum_k,
    })
}

/// Evaluates fine-grid `(uplift_u, lithology_id)` directly from an upsampled `fine_bedrock_h`
/// at initial time `t_elapsed_yr = 0.0` (`80 MiB` total @ `4096^2`).
pub fn generate_fine_s1_aux(
    cfg: &WorldV2Config,
    fine_bedrock_h: &[f32],
    params_grid_size: u32,
) -> Result<(Vec<f32>, Vec<u8>), ConfigError> {
    generate_fine_s1_aux_at_time(cfg, fine_bedrock_h, params_grid_size, 0.0, 0.0)
}

/// Evaluates fine-grid `(raw uplift_u, advected lithology_id)` from `fine_bedrock_h` at `t_elapsed_yr`
/// using `uplift_m_yr_scale` for the rock-advection term `U * t_elapsed_yr`.
pub fn generate_fine_s1_aux_at_time(
    cfg: &WorldV2Config,
    fine_bedrock_h: &[f32],
    params_grid_size: u32,
    uplift_m_yr_scale: f64,
    t_elapsed_yr: f64,
) -> Result<(Vec<f32>, Vec<u8>), ConfigError> {
    cfg.validate()?;
    let w = cfg.grid_size as usize;
    let h = cfg.grid_size as usize;
    let n = w * h;
    if fine_bedrock_h.len() != n {
        return Err(ConfigError {
            message: format!(
                "fine_bedrock_h length {} does not match {}x{}",
                fine_bedrock_h.len(),
                w,
                h
            ),
        });
    }
    let params = TectonicParams::from_config_with_grid_size(cfg, params_grid_size);
    let denom_x = (w - 1) as f64;
    let denom_z = (h - 1) as f64;
    let extent_m = f64::from(cfg.extent_m);

    let mut uplift_u = vec![0.0_f32; n];
    let mut lithology_id = vec![0_u8; n];

    uplift_u
        .par_chunks_mut(w)
        .zip(lithology_id.par_chunks_mut(w))
        .zip(fine_bedrock_h.par_chunks(w))
        .enumerate()
        .for_each(|(row, ((uu, lid), bh))| {
            let v = row as f64 / denom_z;
            for col in 0..w {
                let u = col as f64 / denom_x;
                let (strat, massif_h, massif_uplift, plateau_blend, _, _, _) =
                    eval_cell_strat_and_envelope(u, v, &params, cfg);
                let _ = massif_h;
                let uplift_raw = (f64::from(cfg.massif_uplift_amplitude) * massif_uplift
                    + 350.0 * plateau_blend
                    + if strat.coast_dist > 0.0 { 120.0 } else { 0.0 })
                .max(0.0);
                let u_m_yr = uplift_raw * uplift_m_yr_scale;
                let class =
                    assign_lithology_advected(bh[col], &strat, u_m_yr, t_elapsed_yr, extent_m);
                uu[col] = uplift_raw as f32;
                lid[col] = class as u8;
                debug_assert!((lid[col] as usize) < LITHOLOGY_CLASS_COUNT);
            }
        });

    Ok((uplift_u, lithology_id))
}

/// Zero-allocation in-place advected stratigraphy update at cumulative time `t_elapsed_yr`.
///
/// Evaluates `z_c(x, y, t) = z_c0(x, y) + U(x, y) * t_elapsed_yr` analytically using only the
/// precomputed `bedrock_h` and `uplift_m_yr` slices (`0 MiB` extra RAM, deterministic across threads).
pub fn update_lithology_advected_in_place(
    cfg: &WorldV2Config,
    params_grid_size: u32,
    bedrock_h: &[f32],
    uplift_m_yr: &[f32],
    t_elapsed_yr: f64,
    lithology_id: &mut [u8],
) -> Result<(), ConfigError> {
    cfg.validate()?;
    let w = cfg.grid_size as usize;
    let h = cfg.grid_size as usize;
    let n = w * h;
    if bedrock_h.len() != n || uplift_m_yr.len() != n || lithology_id.len() != n {
        return Err(ConfigError {
            message: format!(
                "slice lengths ({}, {}, {}) must match {}x{}={n}",
                bedrock_h.len(),
                uplift_m_yr.len(),
                lithology_id.len(),
                w,
                h
            ),
        });
    }
    let params = TectonicParams::from_config_with_grid_size(cfg, params_grid_size);
    let denom_x = (w - 1) as f64;
    let denom_z = (h - 1) as f64;
    let extent_m = f64::from(cfg.extent_m);

    lithology_id
        .par_chunks_mut(w)
        .zip(bedrock_h.par_chunks(w))
        .zip(uplift_m_yr.par_chunks(w))
        .enumerate()
        .for_each(|(row, ((lid, bh), uu))| {
            let v = row as f64 / denom_z;
            for col in 0..w {
                let u = col as f64 / denom_x;
                let (strat, _, _, _, _, _, _) = eval_cell_strat_and_envelope(u, v, &params, cfg);
                let class = assign_lithology_advected(
                    bh[col],
                    &strat,
                    f64::from(uu[col]),
                    t_elapsed_yr,
                    extent_m,
                );
                lid[col] = class as u8;
            }
        });

    Ok(())
}

#[cfg(test)]
mod tests {
    use super::{
        generate_uplift, soft_bound_elevation, update_lithology_advected_in_place, LithologyClass,
    };
    use crate::config::WorldV2Config;
    use crate::{ELEV_MAX_M, ELEV_MIN_M};
    use rayon::ThreadPoolBuilder;

    #[test]
    fn soft_bound_elevation_is_strictly_monotone_and_unpinned() {
        let samples = [
            -8_000.0_f64,
            -2_500.0,
            -1_500.0,
            -900.0,
            -1.0,
            0.0,
            1.0,
            1_000.0,
            4_104.0,
            5_700.0,
            8_000.0,
            20_000.0,
        ];
        let mut prev = f32::NEG_INFINITY;
        for &raw in &samples {
            let y = soft_bound_elevation(raw, ELEV_MIN_M, ELEV_MAX_M);
            assert!(
                y > prev,
                "soft_bound_elevation must be strictly increasing: {raw} -> {y} <= {prev}"
            );
            assert!(
                y > ELEV_MIN_M && y < ELEV_MAX_M,
                "soft_bound_elevation must stay strictly interior: {raw} -> {y}"
            );
            assert_eq!(y < 0.0, raw < 0.0, "sea-level sign mismatch at {raw}");
            prev = y;
        }
    }

    #[test]
    fn advected_lithology_migrates_with_uplift_and_matches_initial_bit_for_bit() {
        let cfg = WorldV2Config::for_size(0x5756_3201, 256);
        let field = generate_uplift(&cfg).expect("S1 256");
        let u_phys: Vec<f32> = field.uplift_u.iter().map(|&u| u * 1.0e-6).collect();
        let mut lith_0 = vec![0_u8; field.bedrock_h.len()];
        let mut lith_1t = vec![0_u8; field.bedrock_h.len()];
        let mut lith_later = vec![0_u8; field.bedrock_h.len()];

        update_lithology_advected_in_place(&cfg, 256, &field.bedrock_h, &u_phys, 0.0, &mut lith_0)
            .expect("update t=0");
        assert_eq!(lith_0, field.lithology_id);

        let pool_1 = ThreadPoolBuilder::new().num_threads(1).build().unwrap();
        pool_1.install(|| {
            update_lithology_advected_in_place(
                &cfg,
                256,
                &field.bedrock_h,
                &u_phys,
                200_000.0,
                &mut lith_1t,
            )
            .expect("update t=200k 1t");
        });
        update_lithology_advected_in_place(
            &cfg,
            256,
            &field.bedrock_h,
            &u_phys,
            200_000.0,
            &mut lith_later,
        )
        .expect("update t=200k mt");
        assert_eq!(lith_1t, lith_later);

        // Upward datum advection `z_c = z_c0 + U * t` must shift stratigraphic beds relative to fixed `h`
        // (exposing underlying beds: e.g. Río Negro sandstone -> basal SoftShale, Cogollo -> Río Negro).
        let shifted = lith_0
            .iter()
            .zip(lith_later.iter())
            .filter(|(&a, &b)| a != b)
            .count();
        assert!(
            shifted >= 200,
            "expected >= 200 cells to transition beds over 200 kyr advection, got {shifted}"
        );
        let rio_negro_to_basal_shale = lith_0
            .iter()
            .zip(lith_later.iter())
            .filter(|(&a, &b)| {
                a == LithologyClass::SandstoneCaprock as u8 && b == LithologyClass::SoftShale as u8
            })
            .count();
        let limestone_to_sandstone = lith_0
            .iter()
            .zip(lith_later.iter())
            .filter(|(&a, &b)| {
                a == LithologyClass::SolubleLimestone as u8
                    && b == LithologyClass::SandstoneCaprock as u8
            })
            .count();
        assert!(
            rio_negro_to_basal_shale > 0 && limestone_to_sandstone > 0,
            "expected strictly down-section unroofing transitions (cap->shale={rio_negro_to_basal_shale}, lime->cap={limestone_to_sandstone})"
        );
    }

    #[test]
    fn a1_caprock_fraction_meets_wv2_1b_band_across_all_17_seeds() {
        let mut seeds = vec![
            57_563_201_u64,
            0x5756_3201,
            42,
            1337,
            314_159,
            2027,
            8191,
            10_022,
            777_777,
            888_888,
            1_234_567,
            20_261_122,
            11,
            99,
            7777,
            539_365_664,
            0xDEAD_BEEF,
        ];
        seeds.sort_unstable();
        seeds.dedup();
        for seed in seeds {
            let cfg = WorldV2Config::for_size(seed, 256);
            let f = generate_uplift(&cfg).expect("S1 256");
            let cap = f
                .lithology_id
                .iter()
                .filter(|&&c| c == LithologyClass::SandstoneCaprock as u8)
                .count() as f64
                / f.lithology_id.len() as f64;
            assert!(
                (0.09..=0.21).contains(&cap),
                "seed={seed}: A1 caprock_frac={cap:.4} outside [0.09, 0.21]"
            );
        }
    }
}
